server {
    listen 80 default_server;

    location /api/health {
        proxy_pass http://localhost:8000/api/health;
        proxy_set_header Host localhost;
        proxy_set_header X-Real-IP $remote_addr;
    }

    location / {
        return 301 https://innovacx.net$request_uri;
    }
}
